  }
  if (!result.FindBool("success").value_or(false)) return RespondNow(WithArguments(std::move(result)));
  result.Set("ownerGeneration", epoch).Set("targetId", target->GetId()).Set("url", url);
  return RespondNow(WithArguments(std::move(result)));
